const CREATIVE_STAGES=[['plan','灵感与策划',['planning','control','idea','requirements','idea-explorer','requirements-planner']],['writer','编剧',['script','novel','screenwriter','story','novel-master','screenplay','adaptation','novel-to-screenplay']],['art','美术',['art','art_director','film-art-director']],['director','导演与特效',['director','director-agent','vfx','vfx-agent']],['making','素材与制作',['assets','seedance-prompt','video_prompt','music','editing']],['review','审核与交付',['review','delivery']]];
const OBJECT_TYPES=[['character','人物'],['scene','场景'],['prop','道具'],['shot','镜头与视频'],['sound','声音'],['final','成片'],['other','其他']];
const CONFIRM_KINDS=new Set(['script','screenplay','source_script','novel','outline','character_bio','style_bible','style','director','vfx','asset','video_prompt']);
function creatorScope(item){return String(item.scope||'');}
function stageOf(module){return CREATIVE_STAGES.find(s=>s[2].includes(module))?.[0]||'making';}
function linkedThread(snap,stage,task=null){const threads=registeredThreads(snap);if(task?.thread_id&&threads.some(t=>t.thread_id===task.thread_id))return task.thread_id;const aliases=CREATIVE_STAGES.find(s=>s[0]===stage)?.[2]||['controller','coordinator','main'];for(const t of threads){if(aliases.includes(t.role))return t.thread_id;}for(const slot of asList(snap.workspace?.slots)){const id=slot.thread_id||slot.observation?.thread_id;if(aliases.includes(slot.role)&&threads.some(t=>t.thread_id===id))return id;}return null;}
function chatButton(snap,stage,task=null,label='进入工作对话 ↗'){const id=linkedThread(snap,stage,task);return id?`<button class="text small" data-open-thread="${esc(id)}">${esc(label)}</button>`:'<button class="text small" data-view="threads">查看工作对话 ↗</button>';}
function creatorTaskRows(snap){return asList(snap.tasks).map(t=>{const output=t.output&&snapshotItems(snap).find(i=>i.target_type==='artifact'&&i.target_id===t.output.artifact_id&&i.version===t.output.version&&!i.deleted);const group=['completed','cancelled'].includes(t.status)?'done':t.status==='submitted'?(['current_adopted','historical_adopted'].includes(output?.adoption?.status)?'done':'pending'):['pending_user','pending_confirmation','needs_user_confirmation','awaiting_user'].includes(t.status)?'pending':t.status==='created'?'planned':'active';return {...t,stage:stageOf(t.module),group,output};});}
function taskCard1180(snap,t){const cp=asList(t.checkpoints).at(-1)||{},label=t.status==='cancelled'?'已取消':{pending:'待确认',active:'进行中',planned:'未开始',done:'已完成'}[t.group];return `<article class="creator-task"><div class="badges">${badge(t.group==='pending'?'pending_review':t.group==='done'?'approved':'',label)}<small>${esc(scopeLabel(t.scope))}</small></div><h3>${esc(t.title||'未命名任务')}</h3><p>${esc(creativeText(cp.completed)||creativeText(t.requirements)||'可在工作对话中查看具体创作要求。')}</p>${t.group!=='done'&&creativeText(cp.next_step)?`<div class="task-next"><small>下一步</small><p>${esc(creativeText(cp.next_step))}</p></div>`:''}${creativeText(cp.unresolved)?`<p class="quiet-note">待解决：${esc(creativeText(cp.unresolved))}</p>`:''}${creativeText(t.requirements)?`<details><summary>创作要求</summary><p>${esc(creativeText(t.requirements))}</p></details>`:''}<div class="actions">${t.output?`<button class="small" data-open-key="${esc(itemKey(t.output))}">阅读成果</button>`:''}${previsTaskButtons(snap,t)}${chatButton(snap,t.stage,t)}</div></article>`;}
function renderTasks(snap,opts={stage:'writer',scope:'',query:''}){const all=creatorTaskRows(snap),stage=CREATIVE_STAGES.find(s=>s[0]===opts.stage)||CREATIVE_STAGES[1],scoped=all.filter(t=>(!opts.scope||creatorScope(t)===opts.scope)&&(!opts.query||[t.title,creativeText(t.requirements)].join(' ').includes(opts.query))),rows=scoped.filter(t=>t.stage===stage[0]);return heading('创作任务','先选择创作环节，再查看该环节的任务。')+`<nav class="creator-tabs" aria-label="创作分类">${CREATIVE_STAGES.map(([id,label],i)=>`<button data-stage="${id}" aria-pressed="${id===stage[0]}"><small>${String(i+1).padStart(2,'0')}</small> ${label}<span>${scoped.filter(t=>t.stage===id).length}</span></button>`).join('')}</nav><div class="toolbar"><label>范围 <select id="creator-task-scope">${optionHTML([...new Set(all.map(creatorScope).filter(Boolean))].map(id=>({id,label:scopeLabel(id)})),opts.scope,'全项目')}</select></label><input id="creator-task-query" type="search" placeholder="查找任务" aria-label="查找任务" value="${esc(opts.query)}"></div><div class="panel-head"><h2>${stage[1]}</h2><small>${rows.length} 项任务 · ${rows.filter(t=>t.group==='pending').length} 项待确认</small></div>${stage[0]==='art'?styleComparisons1180(snap):''}<div class="creator-status-board">${[['pending','待确认','需要你阅读或决定'],['active','进行中','正在推进的创作'],['planned','未开始','已安排，等待推进'],['done','已完成','已结束的任务与成果']].map(([id,label,hint])=>`<section class="creator-column ${id}" data-state="${id}"><h3>${label}<span>${rows.filter(t=>t.group===id).length}</span></h3><p>${hint}</p>${rows.filter(t=>t.group===id).map(t=>taskCard1180(snap,t)).join('')||empty('暂无'+label+'任务')}</section>`).join('')}</div>`;}
function canConfirm(item){return item?.target_type==='artifact'&&!item.deleted&&CONFIRM_KINDS.has(item.kind)&&asList(item.version_roles).includes('latest_working')&&item.adoption?.status!=='current_adopted';}
function creatorRecent(snap){return snapshotItems(snap).filter(i=>!i.deleted&&i.target_type==='artifact'&&asList(i.version_roles).includes('latest_working')).slice().sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at))).slice(0,5);}
function renderOverview(snap){const tasks=creatorTaskRows(snap),pending=tasks.filter(t=>t.group==='pending'),active=tasks.filter(t=>t.group==='active'),recent=creatorRecent(snap),next=pending[0]||active[0]||tasks.find(t=>t.group==='planned'),p=snap.project||{},o=snap.board_library?.overview||{};return heading(p.title||'项目总览',p.intro||'专注故事，按自己的节奏创作。',`<button data-view="projects">项目设置</button>`)+`<div class="creator-flow">${CREATIVE_STAGES.map(([id,label],i)=>`<button data-stage="${id}"><small>${String(i+1).padStart(2,'0')}</small> ${label}<span>${tasks.filter(t=>t.stage===id&&t.group!=='done').length} 项待推进</span></button>`).join('')}</div><div class="creator-focus"><section class="creator-hero"><small>接下来，做这件事</small><h2>${esc(next?.title||'从你现在最想解决的事情开始')}</h2><p>${esc(creativeText(asList(next?.checkpoints).at(-1)?.next_step)|| (next?.group==='pending'?'阅读成果，确认或提出修改。':'可以带着一个想法，或已有内容，在工作对话中继续。'))}</p><div class="actions">${next?.output?`<button class="primary" data-open-key="${esc(itemKey(next.output))}">阅读成果 →</button>`:chatButton(snap,next?.stage||'plan',next,'进入工作对话 ↗')}</div></section><section class="creator-attention"><div class="panel-head"><h2>需要你处理 <small>${pending.length?pending.length+' 件':''}</small></h2><button class="text" data-view="reviews">确认记录 ↗</button></div>${styleComparisons1180(snap)}${pending.length?pending.slice(0,3).map(t=>`<div class="record-row"><div><h3>${esc(t.title)}</h3><p class="dim">${esc(scopeLabel(t.scope))}</p>${t.output?`<button class="text small" data-open-key="${esc(itemKey(t.output))}">阅读并处理 →</button>`:chatButton(snap,t.stage,t)}</div>${badge('pending_review','待确认')}</div>`).join(''):empty('当前没有登记的待确认任务。')}</section></div><div class="two-col"><section class="panel"><div class="panel-head"><h2>最近成果</h2><button class="text" data-view="documents">查看全部 ↗</button></div>${recent.length?recent.map(i=>`<div class="record-row"><div class="record-main"><strong>${esc(i.title)}</strong><small>${esc(KIND_LABELS[i.kind]||'创作文稿')} · 第 ${i.version} 版 · ${esc(scopeLabel(i.scope))}</small>${badge(i.adoption?.status,i.adoption?.status==='current_adopted'?'当前采用':'候选')}</div><button class="small" data-open-key="${esc(itemKey(i))}">阅读</button></div>`).join(''):empty('创作成果准备好后，会出现在这里。')}</section><section class="panel"><div class="panel-head"><h2>当前任务</h2><button class="text" data-view="tasks">查看全部 ↗</button></div>${tasks.filter(t=>t.group!=='done').slice(0,3).map(t=>taskCard1180(snap,t)).join('')||empty('暂时没有安排任务。')}</section></div>`;}
function objectsFor(snap){return asList(snap.creator_board?.objects);}
function linkedItems(snap,obj){const links=asList(snap.creator_board?.links);return snapshotItems(snap).filter(i=>!i.deleted).map(item=>{const link=links.find(l=>l.target_type===item.target_type&&l.target_id===item.target_id&&(l.version||null)===(item.version||null));return {item,link};}).filter(x=>x.link?x.link.object_id===obj.object_id:x.item.asset_id===obj.object_id);}
function selectionFor(snap,oid,purpose){return asList(snap.creator_board?.selections).find(s=>s.object_id===oid&&s.purpose===purpose);}
function isSelected(snap,oid,x){const chosen=selectionFor(snap,oid,x.link?.purpose);return !!chosen&&chosen.reference.target_type===x.item.target_type&&chosen.reference.target_id===x.item.target_id&&(chosen.reference.version||null)===(x.item.version||null)&&chosen.reference.sha256===x.item.sha256;}
function thumbSlot(item,label='预览'){return item&&['image','video'].includes(item.media_kind)?`<div class="creator-thumb" data-thumbnail="${esc(itemKey(item))}"><span>正在读取${label}…</span></div>`:`<div class="creator-thumb empty-thumb"><span>${item?.media_kind==='audio'?'♫ 音频素材':item?'文稿与设定':'尚未准备素材'}</span></div>`;}
function renderObjectCards(snap,type,query='',status='',scope=''){const objects=objectsFor(snap).filter(o=>o.type===type&&(!scope||o.scope===scope)&&(!query||[o.title,o.intro].join(' ').includes(query))).filter(o=>{const rows=linkedItems(snap,o),chosen=rows.some(x=>isSelected(snap,o.object_id,x)),pending=rows.some(x=>x.link&&!x.link.reference_only&&!selectionFor(snap,o.object_id,x.link.purpose));return !status||status==='selected'&&chosen||status==='pending'&&pending||status==='empty'&&!rows.length;});return objects.length?`<div class="creator-object-grid">${objects.map(o=>{const rows=linkedItems(snap,o),cover=rows.find(x=>isSelected(snap,o.object_id,x))||rows.find(x=>x.item.target_type==='media'&&!x.link?.reference_only),selected=cover&&isSelected(snap,o.object_id,cover),pending=new Set(rows.filter(x=>x.link&&!x.link.reference_only&&!selectionFor(snap,o.object_id,x.link.purpose)).map(x=>x.link.purpose));return `<article class="creator-object"><button class="object-cover" data-object="${esc(o.object_id)}">${thumbSlot(cover?.item)}<span class="cover-note">${selected?'当前选用':cover?'候选预览 · 尚未选用':'尚无素材'}</span></button><div class="object-copy"><h3>${esc(o.title)}</h3><p>${esc(o.intro||'可以进入详情整理这个对象的素材。')}</p>${pending.size?badge('pending_review',pending.size+' 项用途待选择'):selected?badge('approved','已有选用素材'):badge('',rows.length?'素材待整理':'尚无素材')}<div class="object-foot"><small>${rows.length} 份素材 · ${esc(scopeLabel(o.scope))}</small><button class="text" data-object="${esc(o.object_id)}">查看素材 →</button></div></div></article>`;}).join('')}</div>`:empty('这个分类下还没有符合条件的对象。可以添加人物或场景，再关联已有素材。');}

function styleComparisons1180(snap){const art=snap.art||{};return asList(art.comparisons).filter(c=>!asList(c.stale_reasons).length).map(c=>{const selected=art.active_selection?.comparison_id===c.comparison_id;return `<div class="record-row"><div><h3>${esc(c.title)}</h3><p class="dim">${selected?'已选方案，可在美术工作对话中继续':'视觉方向有方案待选择'}</p></div><button class="small" data-style-compare="${esc(c.comparison_id)}">${selected?'查看方案':'比较方案'}</button></div>`;}).join('');}
